import{_ as t,c as a,o as s,al as r,aG as o,aH as i,aI as l,aJ as n,aK as m}from"./chunks/framework.BUk2DuAG.js";const b=JSON.parse('{"title":"Estim Module","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/estim.md","filePath":"en/modules/estim.md"}'),c={name:"en/modules/estim.md"};function p(u,e,d,h,_,f){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="estim-module" tabindex="-1">Estim Module <a class="header-anchor" href="#estim-module" aria-label="Permalink to “Estim Module”">​</a></h1><p>Basically, the e-stim module consists of a modified 2B Power Box from E-STIM Systems. The battery backup has been completely removed. I also replaced the voltage regulator so that I can work better with a 12V supply. Otherwise, the intensity is more difficult to control.</p><p>I&#39;ve kept the operation almost identical to the 2B. This means the Estim module can also work like a 2B without a reverse connection. This is quite practical because I can also use it to conduct tests with new electrodes.</p><p>I deliberately routed the connections to the control board externally. This allows me to also use the Commander software from E-STIM Systems. However, I have since adapted its functionality to my needs and created my own software interface for it.</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to “Structure”">​</a></h2><p><a href="/images/modules/estim/estim_modul_structure.png" target="_blank"><img src="'+o+'" alt="Estim Modul Structure"></a></p><h2 id="multiplexer" tabindex="-1">Multiplexer <a class="header-anchor" href="#multiplexer" aria-label="Permalink to “Multiplexer”">​</a></h2><p>Regarding the module&#39;s control functionalities, I decided to integrate a multiplexer. This allows me to create four outputs from the two channels A and B. Of course, the four outputs cannot be operated simultaneously. Nevertheless, four electrodes can be switched between two channels.</p><h2 id="case" tabindex="-1">Case <a class="header-anchor" href="#case" aria-label="Permalink to “Case”">​</a></h2><p><a href="/images/modules/estim/estim_case_frontpanel.png" target="_blank"><img src="'+i+'" alt="Estim Case Frontpanel"></a></p><p><a href="/images/modules/estim/estim_case_backpanel.png" target="_blank"><img src="'+l+'" alt="Estim Case Backpanel"></a></p><p><a href="/images/modules/estim/estim_case_multiplexer_frontpanel.png" target="_blank"><img src="'+n+'" alt="Estim Case Multiplexer Frontpanel"></a></p><p><a href="/images/modules/estim/estim_case_multiplexer_backpanel.png" target="_blank"><img src="'+m+'" alt="Estim Case Multiplexer Backpanel"></a></p>',13)])])}const k=t(c,[["render",p]]);export{b as __pageData,k as default};
